import {section,table as baseTable,cite,topic,mountTopic} from './topic-tools.js';
import {texEq as eq,inlineMath} from './math.js';
import {visionScenes,mountVisionScenes} from './vision-scenes.js';
export const visionMeta={slug:'models/vision',title:'Self-Supervised Vision Learning',description:'Connect global and patch targets, online teachers, masked versus all-token supervision, collapse prevention and Gaussian projection tests; choose evidence for the intended backbone use.',date:'2026-04-08',updated:'2026-10-14',topicPath:['models'],tags:['vision','self-supervised learning','DINO','DINOv2','iBOT','iBOT++','TIPSv2','LeJEPA','SIGReg','KoLeo','EMA','Gaussian','backbone','patch-text alignment','characteristic function'],kind:'dense-topic',prototype:true,visibility:'public',learningGoals:['Specify target, view, mask and gradient ownership for visual pretraining','Distinguish view agreement from between-image representation collapse','Explain the scope and cost of finite projected Gaussian tests','Evaluate frozen, adapted and multimodal backbones without mixing their contracts'],related:['training/objectives','post-training/distillation','math/probability','training/practice','models/vision-detection','training/frontier-recipes','models/compact-recipes']};
export const visionAliases=["ai/training/losses/self-supervised/ibot","ai/training/losses/self-supervised/lejepa","ai/training/losses/regularization/sketched-isotropic-gaussian-regularization"];
export const visionSections=[['question','What should a reusable visual backbone preserve?'],['tokens','Separate image features, patch features and loss heads'],['target-contracts','Choose what the model predicts'],['ibot','iBOT: learn an online visual tokenizer'],['patch-loss','Categorical patch targets, not cosine regression'],['mask-animation','Input masking and loss selection are different operations'],['teacher','A stopped target and a moving teacher'],['centering','Centering, sharpening and prototype allocation'],['head-ownership','Shared or separate heads depends on the recipe'],['ibot-evidence','Keep pretraining and evaluation conditions attached'],['dinov2','DINOv2: make global and local training scale together'],['koleo','Spread features without calling them Gaussian'],['vision-systems','Preserve crop boundaries while packing computation'],['features','Read feature visualizations as qualitative evidence'],['ibot-plus','iBOT++: supervise visible predictions too'],['text-alignment','Patch-text alignment needs a text learning path'],['tips-recipe','Head-only EMA and captions at different granularities'],['tips-evidence','One ablation is not every downstream task'],['lejepa','LeJEPA: agreement plus distribution regularization'],['agreement','View agreement alone admits collapse'],['agreement-identity','Centered agreement is not identical to pairwise agreement'],['gaussian-target','Why isotropy needs a scale constraint'],['fisher','What the Gaussian optimality argument does—and does not—prove'],['projections','A joint distribution is more than its coordinate marginals'],['projection-experiment','Rotate a direction that reveals the hidden difference'],['cf','Characteristic functions expose more than covariance'],['ecf','Estimate the signature from a batch'],['quadrature','Make the frequency integral and its scale explicit'],['finite-sample','Finite tests have sampling noise and blind spots'],['complexity','Linear complexity means fixed slices and frequencies'],['implementation','Two small loss contracts with explicit reductions'],['multimodal-recipes','Pretrained, joint and encoder-free visual paths'],['token-budget','Resolution and merging set the language-side token cost'],['training-boundaries','A visual input interface is not an SSL recipe'],['evaluation','Evaluate the feature contract you intend to use'],['history','Related branches, not one mandatory sequence'],['sources','Sources and connected topics']];
const p=x=>'<p>'+x+'</p>',code=x=>'<pre><code>'+x.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;')+'</code></pre>';
const table=(caption,heads,rows)=>baseTable(caption,heads,rows).replace('class="dense-table-wrap"','class="dense-table-wrap" tabindex="0" role="region" aria-label="'+caption+'"');
export function visionReader(link){const scenes=visionScenes(),parts=[],related=(s,t)=>'<a href="'+link(s)+'">'+t+'</a>',add=(id,body)=>parts.push(section(id,visionSections.find(x=>x[0]===id)[1],body));
add('question',p('A reusable backbone must preserve information that several later tasks can use. Recognizing an entire image and locating one part are related, but different, requirements. A global representation can support classification while losing the spatial distinctions needed for segmentation or depth.')+p('Self-supervised learning (SSL) creates training targets from the data rather than requiring a task label for every image. The target can be pixels, prototype probabilities or another view’s features. That choice determines which differences the encoder is asked to retain.')+p('There are two separate questions: what should related views agree on, and what prevents every image from receiving the same representation? Start with the target contract. Then inspect the anti-collapse mechanism. Finally, evaluate the exact feature interface you intend to reuse.'));
add('tokens',p('For a batch of B images with P patches, a transformer can expose patch features [B,P,D] and one global class-token feature [B,D]. D is the backbone width. A projection head can map those features to K prototype logits, giving [B,P,K] or [B,K].')+p('Prototype probabilities are training targets, not automatically calibrated semantic labels. A prototype can organize visual similarity without meaning a named class such as “wheel.” The downstream application can use backbone features rather than the prototype head.')+p('Keep spatial correspondence explicit. Same-view teacher and student patch positions can match directly when the student masks some inputs. Crops of different locations require coordinate correspondence before a patchwise comparison. A global cross-view loss does not need that same patch-index identity.'));
add('target-contracts',table('Different targets require different losses',['Family','Predicted target','Important distinction'],[['Pixel reconstruction / MAE','Image pixels or normalized patch pixels','No fixed discrete tokenizer is required'],['Discrete-token reconstruction / BEiT','Codes from a separately learned visual tokenizer','The target representation is supplied by another tokenizer'],['DINO / iBOT-style distillation','Teacher prototype probability distributions','Cross-entropy is applied after the projection head'],['Continuous feature regression','Teacher or related-view feature vectors','MSE or cosine regression is a different contract']])+eq("\\begin{aligned}L_{\\mathrm{cos}}&=1-\\frac{z_s^\\top z_t}{\\|z_s\\|_2\\|z_t\\|_2}\\\\ \\|z_s-z_t\\|_2^2&=2(1-z_s^\\top z_t)\\quad(\\|z_s\\|_2=\\|z_t\\|_2=1)\\end{aligned}","Finite vectors must have the same dimension and nonzero norms. The second identity requires unit vectors. These feature-regression alternatives are not the original categorical iBOT objective.")+p('Do not infer that pixel targets make dense features universally weak, or that global distillation has no target. Compare the complete architecture, training scale and evaluation. '+cite('https://arxiv.org/abs/2111.06377','MAE')+' and '+cite('https://arxiv.org/abs/2106.08254','BEiT')+' illustrate the two reconstruction contracts.'));
add('ibot',p('iBOT means Image BERT Pre-Training with Online Tokenizer. A teacher generates patch-level distributions as training proceeds. The student predicts those targets from a masked version of the same view. There is no separate fixed-tokenizer pretraining stage.')+p('A second objective aligns class-token predictions across views. This global objective supports semantic organization of the online targets. The patch objective adds a local prediction requirement. The two losses answer different questions rather than duplicate each other.')+p('“Online” describes how targets evolve. It does not mean that the teacher receives the same backward update as the student. '+cite('https://arxiv.org/abs/2111.07832','iBOT')+' uses a moving teacher and stopped target predictions.'));
add('patch-loss',eq("\\begin{aligned}p_{s,i}&=\\operatorname{softmax}(z_{s,i}/\\tau_s)\\\\L_{\\mathrm{patch}}&=-\\frac1{|\\mathcal M|}\\sum_{i\\in\\mathcal M}\\sum_{k=1}^K q_{t,i,k}\\log p_{s,i,k}\\end{aligned}","The selected masked set must be nonempty for this formula. Teacher rows qₜ are normalized probabilities with stopped gradients; τₛ &gt; 0 and student logits are finite. Declare the image/view/batch mean separately; the empty-set policy is given below.")+eq("\\begin{aligned}L_{\\mathrm{cls}}&=-\\frac1{|\\mathcal C|}\\sum_{(a,b)\\in\\mathcal C}\\sum_{k=1}^{K}q_{t,a,k}\\log p_{s,b,k}\\\\L_{\\mathrm{iBOT}}&=\\lambda_{\\mathrm{patch}}L_{\\mathrm{patch}}+\\lambda_{\\mathrm{cls}}L_{\\mathrm{cls}}\\end{aligned}","C is a nonempty set of valid cross-view class-token pairs. a indexes a teacher global crop; b indexes a different student crop. Targets are stopped normalized distributions, not raw features. This expression is per image; the batch mean and nonnegative loss weights must be declared.")+p('The patch loss keeps same-view spatial correspondence. The class-token loss instead asks different crops to agree globally. Their weights set a tradeoff between local prediction and global agreement; they do not make the two targets identical.')+p('For a selected patch, the logit derivative is (pₛ−qₜ)/(|M|τₛ). A positive component lowers a student logit under gradient descent; a negative component raises it. The target distributes credit across prototypes instead of selecting only one hard code.')+p('Use stable log-softmax, not the logarithm of an already underflowed probability. Normalize teacher rows to sum to one. Specify whether averaging occurs per image, per view or across all selected batch tokens. Those choices change sample weights when mask counts differ.')+p('If M is empty, do not divide by zero. The teaching model explicitly returns zero loss and gradient. A real recipe can instead require at least one masked token. This boundary must be declared.'));
add('mask-animation',scenes.mask+p('The input mask stays fixed when the loss-position switch changes. In masked-only mode, changing visible patch1’s assigned logit does not change this local loss. In all-token mode, that prediction receives its own direct target.')+p('The table shows derivatives with respect to independent output logits. A real transformer couples outputs through context. Visible patch embeddings can affect masked predictions and receive indirect gradients even without a direct loss at their own positions.'));
add('teacher',eq("\\theta_t\\leftarrow m\\theta_t+(1-m)\\theta_s","EMA combines matching parameter arrays after the student update, with 0 ≤ m ≤ 1. Teacher targets do not receive a loss gradient. Momentum is not a learning rate or an anti-collapse guarantee.")+p('Compute teacher targets without retaining a loss gradient through them. Compute student predictions and the declared loss. Backpropagate through the student, update student parameters, then apply the recipe’s teacher update. Keep the teacher’s normalization and state updates explicit.')+p('Momentum controls target lag. An EMA teacher is not a universally sufficient anti-collapse proof. The full view, temperature, centering and objective recipe matters. A frozen larger teacher used for model distillation is another contract; it does not follow the student by EMA. '+related('post-training/distillation','Distillation')+' covers that broader transfer setting.'));
add('centering',p('Centering changes teacher prototype allocation across samples. Sharpening changes each target distribution’s concentration through temperature. These are not the same operation. Nor is centering prototype outputs equivalent to whitening backbone features.')+p('Original iBOT investigates centering and sharpening for patch targets as well as its DINO-style global targets. It is therefore incorrect to describe iBOT as requiring neither. DINOv2 uses three Sinkhorn–Knopp normalization iterations for teacher outputs, while the student uses softmax.')+p('Batch allocation can discourage one prototype from absorbing every sample. It does not prove that each prototype is a named semantic category. Finite batches, distributed aggregation and numerical precision affect the implemented normalization. Preserve the actual target preparation when reproducing a method.'));
add('head-ownership',p('Original iBOT shares projection-head parameters between class and patch tokens. Its ablation supports sharing in that setup. DINOv2 instead uses separate DINO and iBOT heads after finding untying helpful at scale.')+p('These choices are not contradictory laws. The global and local objectives can need different loss-space mappings. Backbone sharing, head sharing and teacher sharing are independent decisions. Record which parameters each objective updates rather than summarize the whole method as simply “shared.”'));
add('ibot-evidence',table('Original iBOT headline values with their conditions',['Result','Conditions'],[['82.3% ImageNet-1K linear probing','ViT-L/16; ImageNet-22K pretraining; 200 pretraining epochs; frozen-backbone linear evaluation'],['87.8% ImageNet-1K fine-tuning','ViT-L/16; ImageNet-22K pretraining; 200 pretraining epochs; 512-resolution fine-tuning']])+p('The second result updates the backbone and uses a higher evaluation/training resolution. It is not a frozen-feature result. Neither number establishes universal dense-task quality. Detection and segmentation need their own protocols. See '+cite('https://arxiv.org/html/2111.07832','iBOT Tables 1–3')+' for the specific comparisons.'));
add('dinov2',p('DINOv2 combines global DINO cross-entropy, masked-patch iBOT cross-entropy and a feature-spreading regularizer. It scales this recipe with curated data, a large teacher and smaller distilled models. Frozen global and patch features are both intended outputs.')+eq("L=\\lambda_{\\mathrm{DINO}}L_{\\mathrm{DINO}}+\\lambda_{\\mathrm{iBOT}}L_{\\mathrm{iBOT}}+\\lambda_{\\mathrm{KoLeo}}L_{\\mathrm{KoLeo}}","Nonnegative assigned weights and declared reductions set the relative scales of global agreement, masked prediction and feature spread. This is a recipe contract, not universal default weights.")+p('Sinkhorn normalization, separate heads, residual stabilization and efficient crop execution support that larger run. A single “DINOv2 loss” label hides these different responsibilities. A reproduction needs the full training contract, not only a sum of three symbols. '+cite('https://arxiv.org/abs/2304.07193','DINOv2')+' describes the combined recipe.'));
add('koleo',eq("\\begin{aligned}\\rho_i&=\\min_{j\\ne i}\\|x_i-x_j\\|_2\\\\L_{\\mathrm{KoLeo}}&=-\\frac1B\\sum_{i=1}^B\\log\\rho_i\\end{aligned}","DINOv2 uses L2-normalized features and a batch with B ≥ 2. The unregularized logarithm requires positive nearest-neighbor distances. A duplicate feature needs an explicit numerical policy; spreading on the unit sphere is not a Gaussian radial target.")+p('Close neighbors receive a large penalty. Minimizing the negative log distance encourages the batch features to spread. The batch, normalization and nearest-neighbor definition are part of the mechanism.')+p('Identical features give zero distance, so the logarithm is not finite. Practical implementations need an explicit epsilon or equivalent numerical policy. B must permit a non-self neighbor. Changes in batch composition change the nearest-neighbor set.')+p('KoLeo is based on differential-entropy estimation. It is not the same as fitting an isotropic Gaussian. Unit-normalized features live on a sphere, whereas a Gaussian has variable radius. The geometry and target constraints differ.'));
add('vision-systems',p('Multi-crop learning mixes long global-crop sequences and shorter local-crop sequences. Packing concatenates those sequences into one compute stream. A block-diagonal attention mask prevents tokens in one crop from reading another crop. Concatenation without that boundary changes the learning problem.')+p('Efficient stochastic depth skips the dropped residual computation rather than calculating it and multiplying the output by zero. DINOv2 uses a 40% drop rate. The saved fraction concerns those residual computations; it is not a universal 40% reduction in total training FLOPs.')+p('LayerScale initializes residual branches with small learned diagonal multipliers. Its role is residual stabilization, not target normalization. Fused kernels, sharding and attention layouts address execution cost; they do not replace the global/local objectives. '+related('training/parallelism','Distributed Training and Parallelism')+' owns sharding and synchronization.'));
add('features',p('Patch-feature PCA can reveal foreground structure and part correspondences across images. DINOv2’s examples include related regions despite pose or appearance differences. Successive components can organize parts such as eyes, wings or wheels.')+p('PCA components have arbitrary sign. A threshold chosen for selected images is not a guaranteed object mask on every input. A visually convincing feature map is useful qualitative evidence, not a segmentation score.')+p('To use a feature visualization, state the feature layer, preprocessing, PCA fit set, component selection and threshold. Fit and evaluate learned readouts separately. Otherwise a selected image can hide failures or preprocessing dependence.'));
add('ibot-plus',p('Masked prediction supplies direct targets only at selected masked positions. Visible tokens can support reconstruction without being directly anchored to their corresponding teacher predictions. That distinction motivates iBOT++ within TIPSv2.')+eq("L_{\\mathrm{iBOT++}}=-\\frac1P\\sum_{i=1}^P\\sum_{k=1}^K q_{t,i,k}\\log p_{s,i,k}","P ≥ 1 counts all patch predictions, with normalized stopped teacher targets. The input can remain masked: the loss includes visible as well as masked positions. Declare the per-image and per-view reduction when combining samples.")+p('All-token supervision changes both the selected positions and, under the mean convention here, the denominator. It does not mean “remove masking from the input.” Removing masking during a separate distillation stage is another choice.')+p('The proposed explanation is stronger anchoring of local semantics. The tested improvement belongs to the full training and evaluation setup; all-token supervision is not guaranteed to help every target, augmentation or domain.'));
add('text-alignment',p('A visual teacher target is not itself a text embedding. iBOT++ matches visual prototype distributions. TIPSv2 also has an image-text learning path. That shared training context is what makes patch-text alignment a meaningful capability to evaluate.')+p('For zero-shot segmentation, compare patch features with embeddings of class names and assign spatial labels under a declared upsampling/inference protocol. This is different from fitting a supervised segmentation head.')+p('A distilled student can outperform its teacher on a particular feature use. Changed initialization, loss positions and optimization can reorganize representations. That observation is not evidence that all students universally surpass teachers.'));
add('tips-recipe',p('TIPSv2 combines all-token self-distillation, head-only EMA and captions at multiple granularities. The teacher and student share the vision encoder in the head-only design, but the target head remains an EMA copy. This avoids storing a second EMA encoder.')+p('The combined image-text objective supplies another constraint on the encoder. Do not transplant head-only EMA into an SSL-only recipe and assume the same stability. Removing head EMA too is yet another configuration.')+p('Synthetic captions from PaliGemma and Gemini provide different levels of detail alongside web text. More detailed captions are not automatically better alone. Sampling across granularities changes which visual distinctions the model must use. This is a data/objective design choice, not simply a longer-caption rule.'));
add('tips-evidence',table('TIPSv2 cumulative ViT-g ablation: ADE150 zero-shot mIoU',['Configuration','mIoU'],[['Reproduced TIPS with iBOT','3.5'],['Replace iBOT with iBOT++','17.6'],['Then add multi-granularity captions','18.1'],['Then add head-only EMA','19.1']])+p('The iBOT++ change adds 14.1 mIoU points in this experiment. The cumulative ablation uses 100k steps at 224 resolution; it is not the final high-resolution model comparison. Image-only segmentation does not improve in every ablation row.')+p('The paper evaluates 9 tasks across 20 datasets with frozen encoders. Those tasks include global and dense image-text uses as well as image-only uses. A supervised readout and a zero-shot text protocol do not measure the same contract. '+cite('https://arxiv.org/html/2604.12012','TIPSv2 Tables 3–4 and evaluation protocol')+' give the conditions.'));
add('lejepa',p('Agreement objectives can be simple, but their collapse safeguards can become complicated. LeJEPA combines a centered multi-view squared-distance objective with Sketched Isotropic Gaussian Regularization, or SIGReg.')+eq("L_{\\mathrm{LeJEPA}}=(1-\\lambda)L_{\\mathrm{agreement}}+\\lambda L_{\\mathrm{SIGReg}}","For this mixture, 0 ≤ λ ≤ 1. A shared encoder produces the views without an EMA teacher or stopped target branch. The two loss reductions must be fixed before comparing a weight across configurations.")+p('The global-view center remains differentiable. Changing one global embedding changes both its own prediction and the center used by other views. A stop-gradient center implements a different objective.')+p('The core loss can be concise—approximately 50 lines in the paper’s presentation. Data loading, augmentation, model definition, distributed correctness and evaluation still require a full training pipeline. Simpler loss code does not remove those contracts. '+cite('https://arxiv.org/abs/2511.08544','LeJEPA')+' develops the approach.'));
add('agreement',eq("\\begin{aligned}\\mu_n&=\\frac1G\\sum_{g=1}^G z_{n,g}\\\\L_{\\mathrm{agreement}}&=\\frac1{BVD}\\sum_{n=1}^B\\sum_{v=1}^V\\|z_{n,v}-\\mu_n\\|_2^2\\end{aligned}","B images, V views and D coordinates are positive counts; the first 1 ≤ G ≤ V views are global. Each vector has D coordinates. The center stays in the gradient graph; this scalar averages over images, views and coordinates.")+scenes.agreement+p('A constant encoder can make every distance zero. A low agreement loss therefore does not by itself show useful representations. A second term must constrain representation spread or distribution. The example changes within-image agreement and between-image separation independently.'));
add('agreement-identity',p('Be precise when replacing pairwise global-to-all distances with distance to the mean. For any set of global vectors g and comparison vectors a, the exact identity contains an additional variance term.')+eq("\\begin{aligned}\\mu&=\\frac1G\\sum_{g=1}^G g_g\\\\\\frac1{GA}\\sum_{g=1}^G\\sum_{a=1}^A\\|g_g-a_a\\|_2^2&=\\frac1A\\sum_{a=1}^A\\|\\mu-a_a\\|_2^2+\\frac1G\\sum_{g=1}^G\\|g_g-\\mu\\|_2^2\\end{aligned}","Both finite sets are nonempty and have the same vector dimension. The final term is global-view variance. It need not vanish or remain constant while the encoder learns; independence is not required for this algebraic identity.")+p('For global and all-view scalars −1,+1, the centered loss is 1 while the pairwise loss is 2. The missing term is 1. The LeJEPA v3 paper’s Eq6→7 and Appendix B.6 omit this term. The centered loss shown in its implementation is a valid declared objective, but not an exact equality to that pairwise loss.')+p('This algebraic distinction does not invalidate reported experiments using the implemented centered objective. It matters when deriving gradients or writing a reproduction from the pairwise formula. '+cite('https://arxiv.org/html/2511.08544v3','LeJEPA v3, Eq6–7 and Appendix B.6')+' provides the version-specific derivation.'));
add('gaussian-target',p('An isotropic covariance treats every direction equally. But its scale must be fixed. A distribution with covariance sI is isotropic for any positive s; only s=1 gives identity covariance.')+eq("\\begin{aligned}\\Sigma=sI,\\quad\\operatorname{tr}(\\Sigma)=T&\\ \\Longrightarrow\\ s=T/D,\\quad\\Sigma=(T/D)I\\\\T=D&\\ \\Longrightarrow\\ \\Sigma=I\\end{aligned}","D ≥ 1 and T &gt; 0 fix the scale of an already isotropic covariance. A fixed trace alone does not imply isotropy; isotropy alone does not fix the scale.")+p('Gaussian matching goes beyond a covariance penalty. Means, variances and pairwise covariances can all match the target while higher-order structure differs. The next example isolates that failure rather than relying on a high-dimensional picture.'));
add('fisher',p('The Fisher information functional measures the expected squared magnitude of the density’s score gradient, '+inlineMath(String.raw`\nabla\log p`)+'. Here “score” refers to a density derivative, not a prediction confidence.')+eq("\\begin{aligned}J(p)&=\\mathbb E_{z\\sim p}\\|\\nabla\\log p(z)\\|_2^2\\\\J(p)&\\ge\\operatorname{tr}(\\Sigma^{-1})\\end{aligned}","For a regular density with fixed positive-definite covariance Σ, finite Fisher information and valid integration-by-parts boundary conditions. The Gaussian attains the bound under these assumptions, not an unconditional downstream-task optimum.")+p('With a fixed covariance trace T, minimizing '+inlineMath(String.raw`\sum_{j=1}^D\frac1{\lambda_j}`)+' favors equal positive eigenvalues. By Cauchy–Schwarz, that sum is at least '+inlineMath(String.raw`\frac{D^2}{T}`)+'. This gives the isotropic Gaussian as the minimizer of this functional under the constraint.')+p('The paper connects this geometry to downstream risk through specified task and estimator models, including linear-probe sensitivity and asymptotic nonlinear-estimator bias. Those assumptions matter. Distribution shape alone cannot prove that an encoder retains the labels needed for every possible task.')+p('For example, an encoder could preserve the desired marginal shape while discarding one task-relevant distinction. View construction and feature information remain essential. The argument motivates a regularizer; it is not an unconditional all-task optimality certificate.'));
add('projections',p('Cramér–Wold relates a joint distribution to all one-dimensional linear projections. Checking only the coordinate axes is weaker. Sampling a finite set of random directions is also weaker than checking every direction.')+p('Let '+inlineMath(String.raw`U\sim\mathcal N(0,1)`)+' be a standard Gaussian and '+inlineMath(String.raw`R\in\{-1,+1\}`)+' an independent fair sign. Define '+inlineMath(String.raw`Z=(U,RU)`)+'. Both coordinates are standard Gaussian, and covariance is identity. Yet Z lies on two diagonals, not throughout the plane.')+p('The 45° projection is '+inlineMath(String.raw`\frac{U(1+R)}{\sqrt2}`)+': half its mass is exactly zero and half is a Gaussian with variance 2. Its total variance remains 1. This singular toy law illustrates the insufficiency of marginal/covariance checks; it is not a counterexample to a theorem requiring a smooth density.'));
add('projection-experiment',scenes.projection+p('First compare the diagonal law at 0° and 45°. Then compare it with the isotropic Gaussian. Rotation changes the projected distribution while leaving the joint law fixed. No encoder update is performed.'));
add('cf',eq("\\begin{aligned}\\varphi_X(t)&=\\mathbb E[e^{\\mathrm i tX}]=\\mathbb E[\\cos(tX)]+\\mathrm i\\,\\mathbb E[\\sin(tX)]\\\\X\\sim\\mathcal N(0,1)&\\ \\Longrightarrow\\ \\varphi_X(t)=e^{-t^2/2}\\end{aligned}","X and frequency t are real; i is the imaginary unit. A characteristic function exists without moment assumptions. Both components define the signature; t is not training time.")+p('Near zero, the characteristic function reflects low-order moments when those moments exist. Other frequencies expose further distributional structure. A symmetric zero-mean target has no imaginary component, but an empirical sample can still have one.')+p('Condition on the fair sign in the diagonal example. With sign −1, the 45° projection is zero and its characteristic function is one. With sign +1, the projection is '+inlineMath(String.raw`\sqrt2\,U`)+' and has characteristic function '+inlineMath(String.raw`e^{-t^2}`)+'. Average the two equally likely branches:')+eq(String.raw`\varphi_{45^\circ}(t)=\frac12\cdot1+\frac12 e^{-t^2}=\frac{1+e^{-t^2}}2`,'Exact population mixture for the singular illustrative law, not an empirical batch estimate or an SSL training result.')+p('Both branches together give zero mean and variance one. Those first two moments match the standard Gaussian, but the full signature differs. A covariance-only check cannot express that difference.'));
add('ecf',eq("\\begin{aligned}x_{n,m}&=z_n^\\top a_m,\\quad\\|a_m\\|_2=1\\\\\\widehat\\varphi_m(t)&=\\frac1B\\sum_{n=1}^B e^{\\mathrm i t x_{n,m}}\\\\E_m(t)&=\\left(\\frac1B\\sum_{n=1}^B\\cos(tx_{n,m})-e^{-t^2/2}\\right)^2+\\left(\\frac1B\\sum_{n=1}^B\\sin(tx_{n,m})\\right)^2\\end{aligned}","B, D and M are positive counts. Project embeddings [B,D] onto M unit directions, stored as columns of [D,M], to obtain [B,M]. The error is the squared complex discrepancy from the standard-normal target.")+p('Unit normalization is necessary: a projection of '+inlineMath(String.raw`\mathcal N(0,I)`)+' onto a vector a has variance '+inlineMath(String.raw`\|a\|_2^2`)+'. Without normalization, the standard-normal target is wrong.')+p('Random directions form a stochastic approximation. Resampling increases directional coverage across updates, but a finite run is not a proof of full Gaussianity. Use reproducible synchronized direction sampling when combining evidence across workers.'));
add('quadrature',eq("\\begin{aligned}L_m&\\approx B\\sum_j w_j e^{-t_j^2/2}\\left|\\widehat\\varphi_m(t_j)-e^{-t_j^2/2}\\right|^2\\\\L_{\\mathrm{SIGReg}}&=\\frac1M\\sum_{m=1}^M L_m\\end{aligned}","Gaussian-windowed Epps–Pulley-style discrepancy with B sample scaling and a mean over M ≥ 1 slices. Quadrature weights include interval widths, endpoint factors and any positive-half doubling; do not apply those factors twice.")+p('The scene uses 17 knots on [0,3], doubles the positive half and gives trapezoid endpoints half weight. The paper also presents 17 knots on [−5,5]. Integration limits, weighting and normalization are configuration choices; do not mix the formulas and keep the same λ as if the scale were unchanged.')+p('For real samples, the negative-frequency characteristic value is the conjugate of the positive one. With a symmetric real target and window, the squared discrepancy is even. That justifies positive-half doubling, not omission of endpoint weights.')+p('Across workers, combine cosine and sine sample sums and counts before squaring their difference from the target. Averaging already squared worker losses gives a different result. Unequal worker counts require a count-weighted mean.'));
add('finite-sample',eq("\\mathbb E\\left|\\widehat\\varphi(t)-q(t)\\right|^2=\\frac{1-|\\varphi(t)|^2}{B}+|\\varphi(t)-q(t)|^2","For B ≥ 1 independent identically distributed projected samples, population characteristic function φ and a deterministic complex target q. The first term is sampling noise; the second is population mismatch. This is not a p-value or a guarantee on untested directions.")+p('Even when the population matches the target, the finite-batch discrepancy generally remains positive at nonzero frequencies. Increasing B reduces that sampling contribution. Multiplying by B changes its scale rather than making it disappear.')+p('A zero discrepancy on selected frequencies and directions does not prove that all untested projections match. Conversely, a positive empirical loss does not alone prove a population mismatch. A calibrated hypothesis test needs its null reference and significance rule; a training loss is not automatically a p-value.')+p('Finite sketches trade coverage for cost. A 256-direction setting is an example, not a Cramér–Wold guarantee. Analyze more directions, different seeds and held-out projections before drawing distributional conclusions.'));
add('complexity',table('Name every scaling axis',['Operation','Direct cost / storage'],[['Project B embeddings of width D onto M directions','O(BDM) operations; [B,M] projected values'],['Evaluate T frequencies for each projected batch','O(BMT) operations; naive [B,M,T] temporary'],['Materialize directions','O(DM) storage'],['Covariance-matrix regularization','A direct [D,D] covariance has quadratic D storage']])+p('SIGReg is linear in D when M and T are held fixed. It is not independent of slice count or batch size. Chunking frequency or sample dimensions can reduce temporary memory, with corresponding reduction and autograd contracts.')+p('The covariance comparison describes a direct implementation, not a claim that every other anti-collapse algorithm necessarily has the same cost. Measure the actual kernel and communication path. A compact equation is not a latency measurement.'));
add('implementation',p('This patch-loss sketch assumes student logits [B,P,K], normalized stopped teacher targets of the same shape, and a Boolean selected mask [B,P]. Empty selection needs the explicit policy shown. It does not replace target preparation or teacher updates.')+code('q = teacher_targets.detach()\nlog_p = log_softmax(student_logits / tau_s, dim=-1)\nce = -(q * log_p).sum(dim=-1)  # [B, P]\ncount = selected.sum()\nif count > 0:\n    patch_loss = ce[selected].sum() / count\nelse:\n    patch_loss = student_logits.sum() * 0')+p('For centered agreement, keep both global embeddings and their center in the gradient graph. This sketch uses [V,B,D], the first G global views and a mean over coordinates as well as views/images.')+code('z = encode_views(views)  # [V, B, D]\ncenter = z[:G].mean(dim=0)  # [B, D], no detach\nagreement = (z - center[None]).square().mean()\nregularizer = mean(sigreg(z[v]) for v in range(V))\nloss = (1 - lambd) * agreement + lambd * regularizer')+p('These are teaching pseudocode, not benchmarked training implementations. Test masks, target-row sums, same-view correspondence, precision, gradients and reductions. Use the actual distributed autograd implementation when feature statistics communicate between workers.'));
add('multimodal-recipes',p('A useful visual backbone can enter a language system through several paths. The paths differ in training order and gradient ownership, not simply in model size.')+table('Reported integration choices—not a controlled ranking',['Model example','Visual learning path','Boundary to preserve'],[['DeepSeek-V4.1-Flash','SigLIP-style bootstrap → auxiliary generative alignment → main model','47B pair exposures; 236B alignment tokens with auxiliary 4B model; transfer encoder, then freeze/unfreeze'],['Kimi K3 / MoonViT-V2','From-scratch joint next-token training','27 layers / ~401M parameters; 14² patches; factorized spatial/temporal attention; reported comparison is not universal'],['Gemma 4 edge models','Frozen pretrained encoders','150M ViT/16; variable aspect and token budget'],['Gemma 4 12B','Encoder-free raw-patch projection','48×48×3 patches; 35M projection; shared decoder learns representations']])+p('DeepSeek initially freezes the encoder except final normalization, keeps its projector trainable, then unfreezes at the language-learning-rate decay with a smaller rate. Its high-resolution bootstrap trials added little final quality in the reported later-stage pipeline. That is stage-specific evidence, not a ban on high-resolution pretraining.')+p('K3 reports that joint from-scratch training matches its SigLIP-initialized baseline with fewer gradient spikes. Its mixture includes captions, interleaved documents, OCR, video, perception and rendered code artifacts. Gemma’s encoder-free experiment is not an equal-compute proof that raw patches always beat frozen encoders.')+p('Keep these source-specific recipes connected to '+related('training/frontier-recipes','Frontier Model Training Recipes')+' and '+related('models/compact-recipes','Small and On-Device Model Recipes')+'. They are applications of visual representations, not additional SSL objectives. Compare the source-specific '+cite('https://huggingface.co/deepseek-ai/DeepSeek-V4.1-Flash/blob/main/DeepSeek_V41_Tech_Report.pdf','DeepSeek report §4.2')+', '+cite('https://github.com/MoonshotAI/Kimi-K3/blob/main/k3_tech_report.pdf','Kimi K3 report')+' and '+cite('https://arxiv.org/abs/2607.02770','Gemma 4 report')+'.'));
add('token-budget',p('Before merging, an image with height H, width W and patch size p has approximately (H/p)(W/p) spatial tokens, subject to processor rounding. Grouping s×s tokens divides that count by s² when the grid is divisible. Channel width or a learned merger must absorb the grouped information.')+p('GLM-5.3-Flash’s reported vision encoder has 24 blocks, width 1024, 16 heads of 64 dimensions and FFN width 4096. It uses 2×14×14 temporal/spatial tubelets and a 2×2 spatial merge. A 448×448 image gives '+inlineMath(String.raw`32\times32=1024`)+' patch positions, then '+inlineMath(String.raw`16\times16=256`)+' language-side positions per temporal tubelet, before processor-specific handling.')+p('The vision blocks use non-causal attention, QK normalization, spatial-temporal positions/RoPE, pre-RMSNorm and clamped SwiGLU. After normalization and merge, a projection reaches language width 4096 with a gated intermediate width 10240. These are released-architecture details, not evidence for a particular SSL pretraining loss.')+p('K3 uses 2×2 token grouping and supports images up to 3584×3584. DeepSeek uses 3×3 pixel unshuffle for a 9× token reduction. Gemma’s frozen encoder path chooses among 70,140,280,560 and 1120 output tokens while preserving aspect ratio. Those token limits are not interchangeable evaluation settings.')+p('Compare the vision-encoder token count with the language-side count separately. Compressing after the encoder does not erase all encoder-side attention cost. The text decoder’s KV cache and prefill cost see the final injected sequence. The '+cite('https://huggingface.co/zai-org/GLM-5.3-Flash/blob/main/config.json','GLM-5.3-Flash configuration')+' records the released architecture; it does not disclose the full training recipe.'));
add('training-boundaries',p('An image-capable service does not disclose a backbone pretraining recipe. Apple’s AFM3 announcements establish multimodal/image-input interfaces and a distinct image-generation service, but do not provide a reconstructible vision SSL objective.')+p('Shieldstral inherits a Pixtral vision encoder from Ministral. Its approximately 4.5M multimodal constructed examples, 14-category taxonomy, query variations and asymmetric reranker filtering concern policy classification. Whether and how the vision components are updated remains undisclosed. '+related('models/decision-models','Structured Decision and Safety Models')+' retains the full safety/data recipe.')+p('Likewise, GLM’s reported 30T multimodal exposure does not reveal a complete modality ratio, deduplication or optimizer schedule. Render–inspect–revise agent trajectories train a different behavior from image-only SSL. An architecture configuration and a marketing evaluation cannot fill in an unknown objective.'));
add('evaluation',p('Select the intended interface before selecting a headline number. A frozen global vector, frozen spatial tokens, a fitted readout, a fine-tuned encoder and an end-to-end language system can give very different answers.')+table('Match evidence to the intended use',['Use','Check'],[['Frozen classification/retrieval','Feature layer, normalization, probe/kNN protocol and label budget'],['Dense prediction','Spatial resolution, patch features, head capacity, training labels and metric'],['Zero-shot patch-text segmentation','Text encoder, class prompts, upsampling and sliding-window protocol'],['Multimodal language input','Projection/merging, visual token budget, freeze schedule and task mixture'],['Domain-specific pretraining','Held-out downstream tasks, domain shift, compute and available labels']])+p('Hold augmentation, model size, exposure, optimizer budget and evaluation constant when testing a proposed loss change. Check feature variance, nearest neighbors and held-out direction discrepancies as diagnostics, not replacements for downstream evaluation.')+p('PCA is qualitative. Training-loss correlation can support checkpoint selection within its tested setting; it is not a universal ranking across domains and objectives. Compare the actual readout contract and its uncertainty. '+related('training/practice','Pretraining: Experiments and Run Design')+' covers experiment design; '+related('models/vision-detection','Detection and Spatial Predictions')+' covers a downstream spatial-selection boundary.'));
add('history',p('DINO (2021) develops global visual self-distillation. iBOT’s 2021 preprint, published at ICLR 2022, adds an online masked-patch target. DINOv2 (2023) scales global and local learning with data curation, stabilization and efficient execution.')+p('LeJEPA (2025) is a parallel branch: shared-encoder agreement with explicit distribution regularization. TIPSv2 (2026) combines vision-language supervision with all-token patch distillation and a lighter teacher path. It is not simply the next version of LeJEPA.')+p('Use chronology to track motivating failures: local targets, scale, collapse control, dense text alignment. These branches can share useful ideas without sharing every target, normalization or gradient contract.'));
add('sources','<ul><li>'+cite('https://arxiv.org/abs/2104.14294','DINO (2021)')+' · global visual self-distillation.</li><li>'+cite('https://arxiv.org/abs/2111.07832','iBOT (2021 preprint/2022 conference)')+' · online patch targets, shared heads and evaluation.</li><li>'+cite('https://arxiv.org/abs/2304.07193','DINOv2 (2023)')+' · global/local scale, KoLeo and crop execution.</li><li>'+cite('https://arxiv.org/abs/2511.08544','LeJEPA (2025)')+' · centered agreement, SIGReg and conditional theory.</li><li>'+cite('https://arxiv.org/abs/2604.12012','TIPSv2 (2026)')+' · '+cite('https://gdm-tipsv2.github.io/','TIPSv2 project')+' · iBOT++, head-only EMA and caption granularity.</li></ul>'+p('Use '+related('training/objectives','Losses and Objectives')+' for general loss gradients, '+related('math/probability','Probability and Distributions')+' for distribution contracts, and '+related('post-training/distillation','Distillation')+' for frozen/EMA/on-policy teacher distinctions. For implementation work, preserve shapes, mask ownership and reductions before tuning a loss weight.'));
return topic(visionMeta,visionSections,'First specify what a patch predicts. Then ask what prevents collapse—and which evidence shows that the resulting features are useful.',parts.join(''));
}
export function mountVision(scope=document){mountTopic(scope,visionMeta.slug,mountVisionScenes);}
